import React from 'react';
import { type Types } from '@fiverr-private/theme';
import { Container } from '@fiverr-private/layout_components';
import { useStepperContext } from '../StepperContext';

const StepContent = ({ children, dataTrackTag = 'stepper_step_content', ...rest }: Types.ContainerProps) => {
  const { orientation } = useStepperContext();

  return (
    <Container paddingBottom={orientation === 'vertical' ? '4' : undefined} dataTrackTag={dataTrackTag} {...rest}>
      {children}
    </Container>
  );
};

StepContent.id = 'StepContent';
StepContent.displayName = 'StepContent';
export default StepContent;
