import React from 'react';
import { Stack } from '@fiverr-private/layout_components';
import { mapResponsiveStyles } from '@fiverr-private/theme';
import { StepperContext } from './StepperContext';
import type { ResponsiveVariant, StepperProps } from './types';

const Stepper = ({
  children,
  stepperProps,
  variant = 'default',
  maxWidth = '100%',
  dataTrackTag = 'stepper',
  ...restProps
}: StepperProps) => {
  const { currentStep, stepStrategy, orientation, completedSteps, ...rest } = stepperProps;
  const isHorizontal = orientation === 'horizontal';

  const gap = mapResponsiveStyles(variant as ResponsiveVariant, (value) => {
    if (value === 'compact') {
      return '2';
    }

    return isHorizontal ? '1' : '0';
  });

  return (
    <StepperContext.Provider value={{ currentStep, completedSteps, stepStrategy, orientation, variant }}>
      <Stack
        as="nav"
        gap={gap}
        padding="1"
        direction={isHorizontal ? 'row' : 'column'}
        overflow="auto"
        maxWidth={maxWidth}
        {...rest}
        {...restProps}
        dataTrackTag={dataTrackTag}
      >
        {children}
      </Stack>
    </StepperContext.Provider>
  );
};

Stepper.displayName = 'Stepper';
export default Stepper;
