import React, { forwardRef, useEffect, useImperativeHandle, useRef } from 'react';
import { Center, Stack } from '@fiverr-private/layout_components';
import { Box, mapResponsiveStyles } from '@fiverr-private/theme';
import { excludeChildrenByType, findChildByType } from '@fiverr-private/ui_utils';
import { useDidMount } from '@fiverr-private/hooks';
import { useStepperContext } from '../StepperContext';
import type { ResponsiveVariant } from '../types';
import StepsDivider, { StepsDividerProps } from './StepsDivider';
import StepIndicator from './StepIndicator';
import type { StepProps } from './types';
import { stepClass } from './styles.ve.css';

const Step = forwardRef<HTMLDivElement, StepProps>(
  (
    { children, overflow, textOverflow, width, stepProps, maxWidth, dataTrackTag = 'stepper_step', dataTrackValue },
    ref
  ) => {
    const { onClick, index, completed, disabled, isLast, ...restStepProps } = stepProps;
    const { orientation, variant, currentStep } = useStepperContext();
    const hidden = mapResponsiveStyles(variant as ResponsiveVariant, (value) => value !== 'default');
    const stepContent = findChildByType(children, 'StepContent');
    const isClickable = Boolean(onClick);
    const innerRef = useRef<HTMLElement>(null);
    const didMount = useDidMount();
    const dividerProps: StepsDividerProps = {
      hidden,
      completed,
      disabled,
      index,
    };

    useImperativeHandle(ref, () => innerRef.current as HTMLDivElement);
    useEffect(() => {
      if (index === currentStep && didMount) {
        innerRef.current?.scrollIntoView?.({ behavior: 'smooth', block: 'nearest', inline: 'center' });
      }
    }, [index, currentStep, didMount]);

    return (
      <Box ref={innerRef} dataTrackTag={dataTrackTag} dataTrackValue={dataTrackValue}>
        <Stack gap="0" alignItems="center">
          <Box
            className={stepClass}
            onClick={onClick}
            boxSizing="borderBox"
            cursor={isClickable ? 'pointer' : undefined}
            outlineColor={{ focusVisible: 'grey_1200' }}
            outlineWidth={{ focusVisible: 'md' }}
            outlineStyle={{
              focusVisible: 'solid',
            }}
            outlineOffset={{ focusVisible: 'sm' }}
            borderRadius="sm"
            whiteSpace="nowrap"
            display="flex"
            alignItems="center"
            gap="1"
            {...restStepProps}
          >
            <StepIndicator isClickable={isClickable} completed={completed} index={index} disabled={disabled} />
            <Box
              hidden={hidden}
              textOverflow={textOverflow}
              width={width}
              overflow={overflow}
              maxWidth={maxWidth}
              color={disabled ? 'grey_700' : 'bodyPrimary'}
              fontWeight="normal"
            >
              {excludeChildrenByType(children, 'StepContent')}
            </Box>
          </Box>
          {orientation === 'horizontal' && !isLast && <StepsDivider {...dividerProps} />}
        </Stack>
        <Stack display="flex" gap="1" hidden={hidden}>
          <Center gap="0" width={16}>
            {orientation === 'vertical' && !isLast && <StepsDivider {...dividerProps} />}
          </Center>
          {stepContent}
        </Stack>
      </Box>
    );
  }
);

Step.displayName = 'Step';
export default Step;
