import React from 'react';
import { Center, Container } from '@fiverr-private/layout_components';
import { CheckCircleSolidIcon } from '@fiverr-private/visuals';
import type { StepProps } from '../types';
import { useStepperContext } from '../../StepperContext';
import { indicatorClass } from '../styles.ve.css';
import { getIndicator } from './styles';

const StepIndicator = ({
  completed,
  index,
  disabled,
  isClickable,
}: Pick<StepProps['stepProps'], 'index' | 'completed' | 'disabled'> & { isClickable: boolean }) => {
  const { currentStep } = useStepperContext();
  const isActive = currentStep === index;

  return (
    <Center
      className={isClickable ? indicatorClass : undefined}
      flexShrink={0}
      gap="0"
      {...getIndicator({ completed, isActive, disabled })}
    >
      {isActive && <Container backgroundColor="white" width="4px" height="4px" borderRadius="circle" />}
      {completed && !isActive && <CheckCircleSolidIcon color={disabled ? 'grey_700' : 'grey_1200'} />}
    </Center>
  );
};

StepIndicator.displayName = 'StepIndicator';
export default StepIndicator;
