import React from 'react';
import { Divider } from '@fiverr-private/layout_components';
import { type Types } from '@fiverr-private/theme';
import { useStepperContext } from '../../StepperContext';
import type { IUseStepper, StepperStep } from '../../../../hooks/useStepper/types';
import { getBorderColor } from './utils';

export interface StepsDividerProps
  extends Pick<StepperStep, 'completed' | 'disabled' | 'optional'>,
    Pick<IUseStepper, 'currentStep'> {
  index?: number;
  hidden?: Types.ResponsiveBooleanType;
}

const StepsDivider = ({ completed, index = 0, hidden }: StepsDividerProps) => {
  const { orientation, currentStep, stepStrategy, completedSteps } = useStepperContext();
  const isHorizontal = orientation === 'horizontal';

  return (
    <Divider
      flex={isHorizontal ? 1 : undefined}
      hidden={hidden}
      direction={orientation}
      marginLeft={isHorizontal ? '1' : undefined}
      marginY="0.5"
      borderWidth="md"
      borderColor={getBorderColor({ completed, currentStep, index, stepStrategy, completedSteps })}
      {...(isHorizontal ? { width: '24px', minWidth: '24px' } : { height: '100%', minHeight: '24px' })}
    />
  );
};

StepsDivider.displayName = 'StepsDivider';
export default StepsDivider;
