import { type Types } from '@fiverr-private/theme';

export const getIndicator = ({ completed, isActive, disabled }): Types.FlexLayoutProps => ({
    width: '16px',
    height: '16px',
    borderRadius: 'circle',
    ...(!completed &&
        !isActive && {
            borderWidth: 'md',
            borderColor: disabled ? 'grey_700' : 'grey_900',
        }),
    ...(isActive && {
        backgroundColor: 'grey_1200',
    }),
});
