import React, { forwardRef } from 'react';
import { Stack } from '@fiverr-private/layout_components';
import { Heading, Text } from '@fiverr-private/typography';
import { Button } from '@fiverr-private/button';
import Stepper from '..';
import useStepper from '../../../hooks/useStepper';
import type { Orientation, StepperStep, StepStrategy } from '../../../hooks/useStepper/types';
import Step from '../Step';
import { StepperProps } from '../types';

export const CurrentStep = forwardRef<HTMLElement, { currentStep: number }>(({ currentStep }, ref) => (
  <Stack padding="8" ref={ref} direction="column" alignItems="center">
    <Heading>Step {currentStep}</Heading>
    <Text>Step {currentStep} content</Text>
  </Stack>
));

CurrentStep.displayName = 'CurrentStep';

export const stepsData: StepperStep[] = [
  { stepId: 1, label: 'Step text 1' },
  { stepId: 2, label: 'Step text 2' },
  { stepId: 3, label: 'Step text 3' },
  { stepId: 4, label: 'Step text 4', disabled: true, optional: true },
  { stepId: 5, label: 'Step text 5' },
];

export const StepperStory = ({
  stepStrategy,
  variant,
  orientation = 'horizontal',
  ...rest
}: {
  stepStrategy: StepStrategy;
  variant?: StepperProps['variant'];
  orientation?: Orientation;
}) => {
  const { stepsProps, currentStep, nextStep, prevStep, setStepCompleteState, stepperProps } = useStepper({
    steps: stepsData,
    stepStrategy,
    orientation,
  });

  return (
    <Stack
      direction={orientation === 'vertical' ? 'row' : 'column'}
      alignItems="center"
      justifyContent={orientation === 'vertical' ? 'spaceEvenly' : 'center'}
    >
      <Stepper {...rest} stepperProps={stepperProps} variant={variant}>
        {stepsProps?.map(({ key, ...rest }, index) => (
          <Step key={key} stepProps={rest}>
            {stepsData[index].label}
          </Step>
        ))}
      </Stepper>
      <Stack direction="column">
        <CurrentStep currentStep={currentStep} {...stepsProps[currentStep]} />
        <Stack>
          <Button
            onClick={() => {
              setStepCompleteState(true);
            }}
          >
            Complete
          </Button>
          <Button onClick={prevStep}>Back</Button>
          <Button onClick={nextStep}>Next</Button>
        </Stack>
      </Stack>
    </Stack>
  );
};

export const Vertical = ({
  stepStrategy,
  orientation = 'horizontal',
  ...rest
}: {
  stepStrategy: StepStrategy;
  orientation: Orientation;
}) => {
  const { stepsProps, currentStep, nextStep, prevStep, setStepCompleteState, stepperProps } = useStepper({
    steps: stepsData,
    stepStrategy,
    orientation,
  });

  return (
    <Stack direction="row" justifyContent="spaceAround">
      <Stepper {...rest} stepperProps={stepperProps}>
        {stepsProps?.map(({ key, ...rest }, index) => (
          <Step key={key} stepProps={rest}>
            {stepsData[index].label}
          </Step>
        ))}
      </Stepper>
      <Stack direction="column">
        <CurrentStep currentStep={currentStep} {...stepsProps[currentStep]} />
        <Stack>
          <Button
            onClick={() => {
              setStepCompleteState(true);
              nextStep();
            }}
          >
            Continue
          </Button>
          <Button onClick={prevStep}>Back</Button>
          <Button onClick={nextStep}>Next</Button>
        </Stack>
      </Stack>
    </Stack>
  );
};
